function isAnagram(s, t) {
    if (s.length !== t.length) return false;
    const map = {};
    for (const c of s) map[c] = (map[c] || 0) + 1;
    for (const c of t) {
        if (!map[c]) return false;
        map[c]--;
    }
    return true;
}
